SET NOCOUNT ON;SET XACT_ABORT ON;ALTER DATABASE CURRENT SET AUTO_UPDATE_STATISTICS_ASYNC ON;UPDATE STATISTICS lab.AscendingData IX_OPT005_Date WITH FULLSCAN;
DECLARE @I int=INDEXPROPERTY(OBJECT_ID(N'lab.AscendingData'),N'IX_OPT005_Date','IndexId');INSERT lab.Evidence SELECT 'EXPLICIT_REFRESH',p.rows,p.modification_counter,MAX(d.EventDate),p.last_updated,(SELECT is_auto_update_stats_async_on FROM sys.databases WHERE database_id=DB_ID()) FROM sys.dm_db_stats_properties(OBJECT_ID(N'lab.AscendingData'),@I)p CROSS JOIN lab.AscendingData d GROUP BY p.rows,p.modification_counter,p.last_updated;PRINT 'SQLPERF_SUMMARY|PASS|OK';
